/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Element;public class H5a extends Element<H5a, Content<?>> {	public static final class Attr {		public static final String download = "download";		public static final String href = "href";		public static final String hrefLang = "hreflang";		public static final String media = "media";		public static final String target = "target";		public static final String mediaType = "type";			}	private static Logger log = LoggerFactory.getLogger(H5a.class);	public H5a() {		super("a");	}	public H5a download(String filename) {		if (EmptyUtil.not(filename)) {			super.getAttrMap().put(Attr.download, filename.trim());		} else {			log.error("download: argument(filename) is empty !");		}		return this;	}	public H5a href(String url) {		if (EmptyUtil.not(url)) {			super.getAttrMap().put(Attr.href, url.trim());		} else {			log.error("href: argument(url) is empty !");		}		return this;	}	public H5a hrefLang(String langCode) {		if (EmptyUtil.not(langCode)) {			super.getAttrMap().put(Attr.hrefLang, langCode.trim());		} else {			log.error("hrefLang: argument(langCode) is empty !");		}		return this;	}	public H5a media(String query) {		if (EmptyUtil.not(query)) {			super.getAttrMap().put(Attr.media, query.trim());		} else {			log.error("media: argument(query) is empty !");		}		return this;	}	public H5a target(String targetType) {		if (EmptyUtil.not(targetType)) {			super.getAttrMap().put(Attr.target, targetType);		} else {			log.error("target: argument(targetType) is empty !");		}		return this;	}	public H5a mediaType(String mediaType) {		if (EmptyUtil.not(mediaType)) {			super.getAttrMap().put(Attr.mediaType, mediaType);		} else {			log.error("mediaType: argument(mediaType) is empty !");		}		return this;	}	@Override	public void build() {		if (super.getAttrMap().containsKey(Attr.href) == false) {			super.getAttrMap().put(Attr.href, "javascript:void(0)");		}		super.build();	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.download:		case Attr.href:		case Attr.hrefLang:		case Attr.media:		case Attr.target:		case Attr.mediaType:			return true;		default:			return super.isAttr(attrName);		}	}	}